SELECT month,CAST(REPLACE(month,'-','') AS INTEGER) AS month_key,country,SUM(CASE WHEN record_class='sale' THEN value_mills ELSE 0 END)/1000.0 AS gross_gbp,-SUM(CASE WHEN record_class='cancellation' THEN value_mills ELSE 0 END)/1000.0 AS cancellations_gbp,SUM(value_mills)/1000.0 AS net_gbp,COUNT(DISTINCT CASE WHEN record_class='sale' THEN invoice END) AS sales_invoices FROM classified WHERE record_class IN ('sale','cancellation') GROUP BY month,country ORDER BY month,country;
